/* four journeys through the body (food, blood, air, water); stops use atlas ids */
const JOURNEYS = [
  { id: 'food', name: L("رحلة الغذاء", "The journey of food"), stops: [
      ["mouth", L("تبدأ الرحلة عند الفم: تلتقط الشفة العليا المشقوقة النباتات، وتطحنها الأضراس بحركات جانبية، ويختلط الطعام باللعاب.", "The journey starts at the mouth: the split upper lip gathers the plants, the cheek teeth grind them with lateral movements, and saliva mixes with the food.")],
      ["esophagus", L("تُدفع اللقمة في المريء بموجة عضلية نازلة حتى تصل إلى المعدة الأولى.", "The bolus is pushed down the oesophagus by a muscular wave until it reaches the first stomach compartment.")],
      ["c1", L("في C1 تبدأ التخمير الميكروبي للألياف، فتنشأ أحماض دهنية قصيرة السلسلة تُستخدم مصدراً للطاقة، ويُمتصّ معها الماء والصوديوم.", "In C1 microbial fermentation of fibre begins, producing short-chain fatty acids that serve as an energy source, alongside absorption of water and sodium.")],
      ["mouth", L("تعود لقم مختارة من C1 إلى الفم في عملية الاجترار: تُعاد مضغ اللقمة ثم تُبلع مرة أخرى، ويمكن لهذه الحلقة أن تتكرّر عشرات المرات في الساعة.", "Selected boluses return from C1 to the mouth in rumination: each bolus is chewed again and re-swallowed, and this loop can repeat dozens of times per hour.")],
      ["c2", L("تنتقل المحتويات إلى C2، وهي أصغر الحجرات، فتُستكمل فيها عملية الامتصاص عبر خلاياها الغدّية.", "Contents move into C2, the smallest compartment, where absorption continues through its glandular cells.")],
      ["c3", L("ثم إلى C3 الأنبوبية: أجزاؤها الأمامية تمتصّ، ونهايتها الخلفية تفرز الحمض والإنزيمات فتقوم عمل المعدة الحقيقية.", "Then into the tubular C3: its cranial part absorbs, and its caudal end secretes acid and enzymes, doing the work of the true stomach.")],
      ["intestine", L("يصل الكيموس إلى الأمعاء الدقيقة، حيث تعادل الصفراء والإنزيمات الحموضة ويفكّك الغذاء إلى جزيئات صغيرة تُمتصّ إلى الدم.", "Chyme enters the small intestine, where bile and enzymes neutralise the acidity and break the food into small molecules that are absorbed into the blood.")],
      ["colon", L("في النهاية تستعيد الأمعاء الغليظة أكبر قدر ممكن من الماء والأملاح، ويتكوّن براز شبه جاف يُطرح خارج الجسم.", "Finally, the large intestine reclaims as much water and electrolyte as possible and forms nearly dry faeces that leave the body.")],
    ] },
  { id: 'blood', name: L("رحلة الدم", "The journey of blood"), stops: [
      ["heart", L("يعود الدم غير المؤكسج من الجسم إلى الأذين الأيمن ثم إلى البطين الأيمن، الذي يدفعه نحو الرئتين.", "Deoxygenated blood returns from the body to the right atrium and then to the right ventricle, which pumps it towards the lungs.")],
      ["lungs", L("في الحويصلات الهوائية ينتقل الأكسجين إلى الدم ويتحرّر ثاني أكسيد الكربون ليخرج مع الزفير.", "In the alveoli, oxygen passes into the blood while carbon dioxide is released to leave with the exhaled air.")],
      ["heart", L("يعود الدم المؤكسج إلى الأذين الأيسر، ويدفعه البطين الأيسر بقوة إلى الأورطي ثم إلى أنحاء الجسم.", "Oxygenated blood returns to the left atrium, and the left ventricle pumps it forcefully into the aorta and on to the rest of the body.")],
      ["blood", L("في الشعيرات الدقيقة يعطي الدم الأكسجين والغذاء للخلايا، ويتحمّل ثاني أكسيد الكربون والفضلات ويعود بها إلى القلب.", "In the capillaries the blood hands oxygen and nutrients to the cells, picks up carbon dioxide and waste, and carries them back to the heart.")],
      ["spleen", L("تمرّ كريات الدم الحمراء في الطحال حيث تُفحص وتُزال القديم أو التالف منها، ويُخزَّن عدد من الصفائح الدموية.", "Red cells pass through the spleen, where they are checked and aged or damaged ones are removed, while platelets are held in reserve.")],
      ["kidneys", L("يتفرّع جزء من الدم إلى الكليتين للتصفية، فتُطرح الفضلات مع قليل من الماء ويُعاد الماء الذي يحتاجه الجسم.", "Part of the blood branches into the kidneys for filtration, so waste leaves with very little water while the water the body needs is returned.")],
      ["heart", L("ثم تعود كل هذه المسارات إلى القلب لتُعاد الدورة، وفي الإبل يعمل القلب بأربع حُجَر مع تغطية دهنية واضحة حول قاعدته وأخدوده التاجي.", "All these routes then return to the heart to begin the cycle again; the camel's four-chambered heart carries prominent fat around its base and coronary groove.")],
    ] },
  { id: 'air', name: L("رحلة الهواء", "The journey of air"), stops: [
      ["nose", L("يدخل الهواء من فتحتي الأنف ويمرّ في ممرات ضيقة بين المحارات الأنفية، فيُدفَّأ ويُرطَّب وتُلتقط منه الجزيئات الغريبة.", "Air enters through the nostrils and passes through narrow meatuses between the nasal conchae, where it is warmed, humidified and cleared of particles.")],
      ["trachea", L("يتابع الهواء طريقه في القصبة الهوائية، وهي أنبوب تدعمه ٦٦-٧٥ حلقة غضروفية، وتزحف أهدابها بالطبقة المخاطية إلى أعلى.", "Air continues down the trachea, a tube supported by 66-75 cartilage rings, whose cilia sweep the mucus layer upwards.")],
      ["lungs", L("يتوزّع الهواء في الرئتين حتى الحويصلات، فيحدث تبادل الغازات: أكسجين إلى الدم وثاني أكسيد كربون إلى الهواء.", "Air spreads through the lungs down to the alveoli, where gas exchange happens: oxygen into the blood, carbon dioxide into the air.")],
      ["blood", L("يحمل الدم الأكسجين إلى الخلايا ويعود بثاني أكسيد الكربون إلى الرئة، وفي الإبل تكون كريات الدم الحمراء بيضوية الشكل وغير معتادة على التحلّل السريع.", "The blood carries oxygen to the cells and returns carbon dioxide to the lung; in camels the red cells are elliptical and unusually resistant to breaking down.")],
      ["nose", L("عند الزفير يمرّ الهواء الساخن الرطب على الأسطح الأنفية الأبرد فيفقد حرارته، وتستعيد هذه الأسطح جزءاً من بخار مائه، ولذلك يخرج الهواء غير مشبع تماماً.", "On exhalation the warm, moist air passes over the cooler nasal surfaces, loses heat and yields part of its water vapour back to the tissue, so the outgoing air is not fully saturated.")],
      ["brain", L("استعادة الحرارة هذه لها فائدة ثانية: يعود دم الأنف البارد إلى جيوب الجمجمة ويمرّ بجوار الشبكة السباتية، فيصل إلى الدماغ دم أقل حرارة من دم الجسم.", "This heat recovery has a second use: cool nasal blood returns to the cranial sinuses alongside the carotid rete, so blood reaching the brain can be cooler than the rest of the body's blood.")],
    ] },
  { id: 'water', name: L("رحلة الماء ولماذا يتحمّل الجمل العطش", "The journey of water, and why camels endure thirst"), stops: [
      ["mouth", L("يبدأ الماء حين يشرب الجمل، وقد سُجّل في تجربة أن جمالاً حُرمت الماء ١١ يوماً شربت نحو ٩٧ لتراً في دقائق معدودة عند إعادة تقديم الماء.", "Water starts when the camel drinks; in one experiment camels deprived of water for 11 days drank about 97 L within a few minutes when water was offered again.")],
      ["esophagus", L("ينزل الماء سريعاً في المريء إلى المعدة الأمامية، لكن امتصاصه إلى الدم أبطأ مما في حيوانات أخرى، وهذا يمنع صدمة أسموزية في الدم.", "Water travels quickly down the oesophagus into the forestomach, but its absorption into the blood is slower than in other animals, which avoids an osmotic shock in the blood.")],
      ["c1", L("في C1 يبدأ امتصاص جزء من الماء، ويستمر فيها السائل الذي يحفظ التخمير الميكروبي، حتى إن اللعاب ظلّ يجري بنحو ٢ لتر في الساعة في اليوم الحادي عشر من العطش.", "Part of the water is absorbed in C1, and the fluid that keeps microbial fermentation going is maintained there; saliva was still flowing at about 2 L/h on the eleventh day of water deprivation.")],
      ["intestine", L("يُكمل الماء طريقه مع الكيموس، ويُمتصّ قسم آخر منه عبر الأمعاء الدقيقة إلى الدم.", "Water continues along with the chyme, and another portion is absorbed through the small intestine into the blood.")],
      ["colon", L("وتستعيد الأمعاء الغليظة ما بقي، فيخرج البراز شبه جاف، وهذه أولى بوابات توفير الماء في الجسم.", "The large intestine reclaims what is left, so the faeces leave nearly dry; this is the body's first water-saving gate.")],
      ["blood", L("يصبح الماء جزءاً من الدم وسوائل الجسم، وكريات الدم الحمراء البيضوية تتحمّل انخفاض تركيز الدم بعد الشرب السريع دون أن تتحلّل. وفي تجربة تحميل بالماء، احتفظ الجمل بالماء الزائد في جسمه أياماً وتحمّل انخفاض تركيز الدم بدلاً من طرحه فوراً، ويستطيع أن يفقد نحو ٢٥٪ من وزن جسمه قبل أن تلحقه أضرار كبيرة.", "The water becomes part of the blood and body fluids, and the elliptical red cells tolerate the fall in blood concentration after rapid drinking without breaking up. In a water-loading experiment camels held the excess water in the body for days and tolerated a diluted blood concentration instead of dumping it immediately, and a camel can lose about 25% of its body mass before serious damage occurs.")],
      ["kidneys", L("تتصفّى الكلية الدم وتعيد معظم الماء إلى الجسم، بمساعدة قمة كلوية غنية بالعُرى الطويلة وحوض به ٢٠-٢٤ تجويفاً يعيد تدوير اليوريا ويرفع تركيز النخاع.", "The kidney filters the blood and returns most of the water to the body, helped by a renal crest rich in long loops of Henle and a pelvis with 20-24 recesses that recycles urea and raises medullary concentration.")],
      ["bladder", L("يخرج البول مركّزاً جداً، فيفقد الجمل من الماء مع البول أقل بكثير مما تفقده حيوانات أخرى بالحجم نفسه.", "Urine leaves very concentrated, so the camel loses far less water in urine than other animals of similar size.")],
      ["nose", L("وتوفّر الأنف طريقاً ثانياً: تبريد هواء الزفير ونزع جزء من بخاره يوفّر نحو ٦٠٪ من الماء مقارنة بإخراج هواء مشبع بحرارة الجسم.", "The nose provides a second route: cooling exhaled air and stripping some of its vapour saves about 60% of the water compared with exhaling saturated air at body temperature.")],
      ["skin", L("الجلد طريق ثالث: لا يبدأ التعرّق إلا عند ارتفاع حرارة الجسم، وحرارة الجسم نفسها تتغيّر يومياً بين نحو ٣٤ و٤١ °م، فيقلّ الماء المفقود بالتبخّر.", "The skin is a third route: sweating starts only once body temperature is already high, and body temperature itself swings between roughly 34 and 41 °C each day, so less water is lost by evaporation.")],
      ["hump", L("والسنام طريق داخلي: هو مخزن دهون لا ماء، وعند حرقه تنتج أكسدة الدهون ماءً أيضياً يساهم في موازنة الماء، ويتراجع حجم السنام في الجفاف الطويل.", "The hump is an internal route: it stores fat, not water, and burning that fat produces metabolic water that helps water balance, while the hump shrinks during long dry periods.")],
    ] },
];

